#!/usr/bin/env python3
"""Generate rtl/twiddle_rom.v: W_64^k = cos - j*sin in Q1.15, k = 0..31.

The values come from python_model/ofdm_fixed.py so hardware and model always agree.
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "python_model"))
from ofdm_fixed import twiddles  # noqa: E402

wr, wi = twiddles()
lines = [
    "// Generated by scripts/gen_twiddle.py - do not edit by hand.",
    "// Twiddle factors W_64^k = cos(2*pi*k/64) - j*sin(2*pi*k/64) in Q1.15.",
    "// inverse = 1 gives the conjugate (used for the IFFT).",
    "module twiddle_rom (",
    "    input             [4:0]  k,",
    "    input                    inverse,",
    "    output reg signed [15:0] wr,",
    "    output     signed [15:0] wi",
    ");",
    "    reg signed [15:0] wi_fwd;",
    "    assign wi = inverse ? -wi_fwd : wi_fwd;",
    "",
    "    always @(*) begin",
    "        case (k)",
]
for k, (r, i) in enumerate(zip(wr, wi)):
    sr = f"-16'sd{-r}" if r < 0 else f"16'sd{r}"
    si = f"-16'sd{-i}" if i < 0 else f"16'sd{i}"
    lines.append(f"            5'd{k:<2}: begin wr = {sr:>11}; wi_fwd = {si:>11}; end")
lines += [
    "            default: begin wr = 16'sd0; wi_fwd = 16'sd0; end",
    "        endcase",
    "    end",
    "endmodule",
    "",
]
out = os.path.join(ROOT, "rtl", "twiddle_rom.v")
open(out, "w").write("\n".join(lines))
print("Wrote rtl/twiddle_rom.v")
